}
```

### 2. Update Metrics Interface

**File:** `opentelemetry-collector/consumer/metrics.go`

```go
type Metrics interface {
    internal.BaseConsumer
    ConsumeMetrics(ctx context.Context, md pmetric.Metrics) error
    // NEW METHOD
    ConsumeMetricsWithContext(ctx context.Context, md pmetric.Metrics, opts ...ConsumeOption) error
}
```

### 3. Update Functional Wrapper

```go
type ConsumeMetricsWithContextFunc func(ctx context.Context, md pmetric.Metrics, opts ...ConsumeOption) error

func (f ConsumeMetricsWithContextFunc) ConsumeMetricsWithContext(ctx context.Context, md pmetric.Metrics, opts ...ConsumeOption) error {
    return f(ctx, md, opts)
}
```

### 4. Update baseMetrics Implementation

```go
type baseMetrics struct {
    *internal.BaseImpl
    ConsumeMetricsFunc
    ConsumeMetricsWithContextFunc // NEW
}
```

### 5. Update NewMetrics Factory

```go
func NewMetrics(consume ConsumeMetricsFunc, options ...Option) (Metrics, error) {
    // Existing implementation
}

// NEW: Factory for context-aware consumption
func NewMetricsWithContext(
    consume ConsumeMetricsFunc,
    consumeWithContext ConsumeMetricsWithContextFunc,
    options ...Option,
) (Metrics, error) {
    if consume == nil && consumeWithContext == nil {
        return nil, errNilFunc
    }
    return &baseMetrics{
        BaseImpl: internal.NewBaseImpl(options...),
